class MyRange(more_itertools.numeric_range):

    def __init__(self, start, stop=None, step=1):
        if stop is None:
            stop = start
            start = 0
        super().__init__(start, stop, step)

def example_iterator():
    for i in range(5):
        yield i

class Counter:

    def __init__(self):
        self.count = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.count >= 3:
            raise StopIteration
        self.count += 1
        return self.count

    def __enter__(self):
        return self

    def __exit__(self, *args):
        pass

class NotReversible:

    def __init__(self, data):
        self.data = data

    def __iter__(self):
        return iter(self.data)

